import test from 'node:test';import assert from 'node:assert/strict';import{compatibilityGround,paintCompatibilityGround}from'../compatibility-ground.js';
test('compatibility terrain retains floor holes and connected trails without canvases or readbacks',()=>{const scene={key:'town',theme:0,width:3,height:3,floor:['...','.#.','...'],doors:[],objects:[]},before=JSON.stringify(scene),paths=[];const g=compatibilityGround(scene,new Set(['0,0','1,0','2,0']),{makePath(loops,radius){const p={loops,radius};paths.push(p);return p;}});assert.equal(paths[0].loops.length,2);assert.equal(paths[1].loops.length,1);assert.equal(JSON.stringify(scene),before);let depth=0;const fills=[],c={save(){depth++;},restore(){depth--;},fill(path,rule){fills.push([path,rule]);}};paintCompatibilityGround(c,g);assert.equal(fills.length,2);assert.equal(depth,0);assert.ok(fills.every(p=>p[1]==='evenodd'));assert.match(g.color,/^rgb\(/);});
